package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.OwnerRegistrationDateInvalidException;

/**
 * Validates the owner's optional {@code registrationDate} WHEN PRESENT: a supplied value must not be
 * later than the server's current date, since a registration cannot be dated in the future. An
 * absent date is left untouched (it later defaults to the server date in {@link BuildOwner}).
 *
 * <p>Reads the body published by {@link RequireOwnerFields}; runs before {@link BuildOwner} so a
 * future date is a 400 via {@link OwnerRegistrationDateInvalidException}, never stored.
 */
public class RequireRegistrationDateNotFuture {

    public void service(@Val OwnerFieldsDto request) throws OwnerRegistrationDateInvalidException {
        LocalDate supplied = request.getRegistrationDate();
        if (supplied != null && supplied.isAfter(LocalDate.now())) {
            throw new OwnerRegistrationDateInvalidException(supplied);
        }
    }
}
=== BuildOwner.java ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Maps the validated body (published by {@link RequireOwnerFields}) to a new {@link Owner}.
 * When the body supplies no registration date, defaults it to the server's current date; either
 * way the effective date is rolled forward off any weekend to the next business day, so every
 * later step (membership number, daily limit) sees the adjusted {@code registrationDate}.
 */
public class BuildOwner {

    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
        Owner owner = ownerMapper.toOwner(request);
        owner.setRegistrationDate(RegistrationDate.effective(request));
        built.set(owner);
    }
}
=== AssignMembershipLevel.java ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's numeric {@code membershipLevel} (1 to 3), scored at creation:
 * start at {@code 1}; add {@code 1} when an email is present; add {@code 1} when
 * {@code namesakeCount} is {@code 0}; capped at {@code 3} (level 4 is reserved for tenure).
 *
 * <p>Runs after {@link AssignNamesakeCount} (so the namesake count is set) and before
 * {@link SaveOwner}, so the level is persisted and available to the create audit line.
 */
public class AssignMembershipLevel {

    public void service(@Val Owner owner) {
        int level = 1;
        String email = owner.getEmail();
        if (email != null && !email.isBlank()) {
            level++;
        }
        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
            level++;
        }
        owner.setMembershipLevel(Math.min(level, 3));
    }
}
=== AssignBulkSignupWarning.java ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's {@code bulkSignupWarning}: {@code true} when more than 80 owners had already
 * been created for this owner's registration day at the moment this owner was created, otherwise
 * {@code false}. The day is the built owner's {@link Owner#getRegistrationDate() registrationDate}
 * (already rolled forward off any weekend by {@link BuildOwner}), matching the accumulation used by
 * {@link RequireDailyOwnerLimit}.
 *
 * <p>Runs after {@link BuildOwner} (so the registration date is set) and before {@link SaveOwner},
 * so the count reflects only the owners that existed before this create.
 */
public class AssignBulkSignupWarning {

    /** A warning is raised once strictly more than this many owners exist for the day. */
    static final long BULK_SIGNUP_THRESHOLD = 80;

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        LocalDate businessDay = owner.getRegistrationDate();
        long createdThatDay = ownerRepository.findAll().stream()
                .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
                .count();
        owner.setBulkSignupWarning(createdThatDay > BULK_SIGNUP_THRESHOLD);
    }
}
